import type { BankQuestion } from "@/lib/bank";

/** p-Block, d-Block and Coordination Compounds (Chemistry (JEE/NEET)): 94 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-p-block-coordination-1","question":"Which noble gas forms the largest number of stable compounds?","options":["Helium","Neon","Argon","Xenon"],"answer":3,"explanation":"Xenon has the lowest ionisation enthalpy among the common noble gases, so it forms fluorides (XeF₂, XeF₄, XeF₆) and oxides (XeO₃, XeOF₄) with the most electronegative elements. Krypton forms only KrF₂.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-2","question":"The oxidation state of iron in [Fe(CN)₆]³⁻ is:","options":["+2","+3","+6","0"],"answer":1,"explanation":"Six CN⁻ ligands contribute −6; for the overall charge of −3 the metal must be +3. [Fe(CN)₆]⁴⁻ is the Fe(II) complex.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-3","question":"Which of the following is a strong-field ligand?","options":["H₂O","F⁻","Cl⁻","CN⁻"],"answer":3,"explanation":"In the spectrochemical series CN⁻ and CO lie at the strong-field end and cause large splitting (pairing of electrons); halides and water are weak-field ligands.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-4","question":"Among the group 15 hydrides, the strongest base is:","options":["NH₃","PH₃","AsH₃","BiH₃"],"answer":0,"explanation":"Basicity decreases down the group (NH₃ > PH₃ > AsH₃ > SbH₃ > BiH₃) because the lone pair sits on a larger, more diffuse orbital and is less available. Reducing power follows the opposite trend.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-5","question":"Zirconium and hafnium have almost identical atomic radii and chemistry. This is a consequence of:","options":["Diagonal relationship","Lanthanoid contraction","Inert pair effect","Similar electronegativity of their oxides"],"answer":1,"explanation":"The poor shielding by 4f electrons causes a steady decrease in size across the lanthanoids, which cancels the expected increase from 4d to 5d. Hence Zr (160 pm) and Hf (159 pm) are nearly the same size and very hard to separate.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-6","question":"The IUPAC name of K₃[Fe(CN)₆] is:","options":["Potassium hexacyanidoferrate(III)","Tripotassium ferricyanide","Potassium ferrocyanide(III)","Potassium hexacyanoferrate(II)"],"answer":0,"explanation":"Cation first, then the anionic complex: six cyanido ligands (hexacyanido) on iron in the +3 state, named 'ferrate' because the complex is an anion. Ferricyanide is the old common name.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-7","question":"The spin-only magnetic moment of a high-spin Mn²⁺ ion is:","options":["1.73 BM","3.87 BM","4.90 BM","5.92 BM"],"answer":3,"explanation":"Mn²⁺ is 3d⁵ with five unpaired electrons in a high-spin state. μ = √(n(n + 2)) = √(5 × 7) = √35 ≈ 5.92 BM. 4.90 BM corresponds to four unpaired electrons (Fe²⁺ high spin).","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-8","question":"Xenon tetrafluoride (XeF₄) has which molecular geometry around xenon?","options":["Tetrahedral","Square planar","See-saw","Octahedral"],"answer":1,"explanation":"Xe in XeF₄ has 4 bond pairs and 2 lone pairs (sp³d² hybridisation). The lone pairs occupy opposite axial positions, leaving the four fluorines in a square plane.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-9","question":"Which of the following is a chelating ligand?","options":["NH₃","Ethane-1,2-diamine (en)","Cl⁻","H₂O"],"answer":1,"explanation":"Ethane-1,2-diamine has two donor nitrogen atoms and binds the same metal at two points to form a five-membered ring (chelate). The other three are monodentate.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-10","question":"In acidic solution, one mole of K₂Cr₂O₇ accepts how many moles of electrons?","options":["2","3","5","6"],"answer":3,"explanation":"Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O. Each Cr goes from +6 to +3 and there are two Cr atoms, so 6 electrons per formula unit; its equivalent mass is M/6.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-11","question":"Which statement about [Ni(CN)₄]²⁻ and [NiCl₄]²⁻ is correct?","options":["Both are tetrahedral and paramagnetic","[Ni(CN)₄]²⁻ is square planar and diamagnetic; [NiCl₄]²⁻ is tetrahedral and paramagnetic","[Ni(CN)₄]²⁻ is tetrahedral and paramagnetic; [NiCl₄]²⁻ is square planar and diamagnetic","Both are square planar and diamagnetic"],"answer":1,"explanation":"Ni²⁺ is d⁸. The strong-field CN⁻ forces pairing, leaving one empty 3d orbital for dsp² hybridisation (square planar, no unpaired electrons). The weak-field Cl⁻ does not pair electrons, so sp³ (tetrahedral) with two unpaired electrons results.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-12","question":"The total number of stereoisomers of [Co(en)₂Cl₂]⁺ is:","options":["3","4","6","2"],"answer":0,"explanation":"The complex has cis and trans geometrical isomers. The trans form has a plane of symmetry, but the cis form is chiral and exists as a pair of enantiomers, giving 1 + 2 = 3 stereoisomers.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-13","question":"The basicity of hypophosphorous acid, H₃PO₂, is:","options":["3","2","1","0"],"answer":2,"explanation":"Basicity counts only the hydrogens bonded to oxygen. H₃PO₂ has one P–OH and two P–H bonds, so it is monobasic; H₃PO₃ (two P–OH) is dibasic and H₃PO₄ is tribasic.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-14","question":"The crystal field stabilisation energy (ignoring pairing energy) of the low-spin complex [Co(NH₃)₆]³⁺ is:","options":["−0.4 Δ₀","−1.8 Δ₀","−2.4 Δ₀","0"],"answer":2,"explanation":"Co³⁺ is d⁶; with the strong-field NH₃ all six electrons occupy the t₂g set (t₂g⁶ eg⁰). CFSE = 6 × (−0.4 Δ₀) = −2.4 Δ₀. A high-spin d⁶ (t₂g⁴ eg²) would give −0.4 Δ₀.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-p-block-coordination-15","question":"The shape of the interhalogen ClF₃ is:","options":["Trigonal planar","Trigonal pyramidal","T-shaped","Trigonal bipyramidal"],"answer":2,"explanation":"Cl has 3 bond pairs and 2 lone pairs (sp³d). The lone pairs take the equatorial positions of the trigonal bipyramid, so the three fluorines form a T shape with bond angles slightly less than 90°.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-16","question":"Which 3d-series element exhibits the largest number of oxidation states?","options":["Scandium","Chromium","Manganese","Zinc"],"answer":2,"explanation":"Manganese (3d⁵ 4s²) shows oxidation states from +2 to +7 because all its 3d and 4s electrons can take part in bonding. Scandium shows only +3 and zinc only +2.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-17","question":"Which ligand can give rise to linkage isomerism?","options":["Ethane-1,2-diamine","NH₃","NO₂⁻","Cl⁻"],"answer":2,"explanation":"An ambidentate ligand such as NO₂⁻ can bind through N (nitrito-N, –NO₂) or through O (nitrito-O, –ONO). SCN⁻ and CN⁻ behave similarly; the other ligands listed have only one donor type.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-18","question":"The oxidation state of sulphur in peroxodisulphuric acid, H₂S₂O₈, is:","options":["+7","+6","+5","+4"],"answer":1,"explanation":"The molecule contains one O–O peroxide linkage, so two oxygens are in the −1 state: 2(+1) + 2x + 6(−2) + 2(−1) = 0 gives x = +6. Treating all eight oxygens as −2 gives the impossible +7 (sulphur has only six valence electrons).","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-19","question":"How many of the following statements are correct? (i) Ce⁴⁺ is a good oxidising agent in aqueous solution. (ii) The most common oxidation state of the lanthanoids is +3. (iii) Actinoids show fewer oxidation states than lanthanoids. (iv) La(OH)₃ is more basic than Lu(OH)₃.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct: Ce⁴⁺ tends to revert to the stable +3 state, and basicity decreases across the series as the ions shrink. (iii) is wrong: actinoids show a wider range of oxidation states (+3 to +7) because the 5f, 6d and 7s levels are close in energy.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-20","question":"Which complex has the highest spin-only magnetic moment?","options":["[Fe(H₂O)₆]²⁺","[Fe(CN)₆]⁴⁻","[Cr(H₂O)₆]³⁺","[Mn(H₂O)₆]²⁺"],"answer":3,"explanation":"Count unpaired electrons: Fe²⁺ (d⁶) with weak-field water is high spin with 4 (4.90 BM); Fe²⁺ with CN⁻ is low spin with 0; Cr³⁺ (d³) has 3 (3.87 BM); Mn²⁺ (d⁵) high spin has 5 (5.92 BM).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-21","question":"Assertion (A): [Fe(CN)₆]³⁻ is only weakly paramagnetic, whereas [Fe(H₂O)₆]³⁺ is strongly paramagnetic. Reason (R): CN⁻ is a strong-field ligand that causes pairing of the d electrons of Fe³⁺.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Fe³⁺ is d⁵. With CN⁻ it is low spin (t₂g⁵, one unpaired electron, 1.73 BM); with water it is high spin (five unpaired electrons, 5.92 BM). The pairing caused by the strong-field ligand is exactly what lowers the moment.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-22","question":"Match the complex with the hybridisation of the central metal. (A) [Ni(CO)₄]; (B) [Ni(CN)₄]²⁻; (C) [Co(NH₃)₆]³⁺; (D) [CoF₆]³⁻. (p) d²sp³; (q) sp³d²; (r) sp³; (s) dsp².","options":["A–r, B–s, C–p, D–q","A–r, B–s, C–q, D–p","A–s, B–r, C–q, D–p","A–s, B–r, C–p, D–q"],"answer":0,"explanation":"Ni(0) in Ni(CO)₄ pairs its 3d⁸4s² into 3d¹⁰ and uses sp³ (tetrahedral). Ni²⁺ with CN⁻ is dsp² (square planar). Co³⁺ (d⁶) with strong-field NH₃ uses inner d orbitals, d²sp³; with weak-field F⁻ it uses outer d orbitals, sp³d² (high spin, paramagnetic).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-23","question":"A complex of formula CoCl₃·4NH₃ gives 1 mol of AgCl per mole when treated with excess AgNO₃. Its structural formula and the number of ions it gives in solution are:","options":["[Co(NH₃)₄Cl₂]Cl, 2 ions","[Co(NH₃)₄Cl]Cl₂, 3 ions","[Co(NH₃)₄]Cl₃, 4 ions","[Co(NH₃)₄Cl₃], 0 ions"],"answer":0,"explanation":"Only chloride outside the coordination sphere is precipitated by Ag⁺. One AgCl means one ionisable Cl⁻ and two Cl⁻ bound to Co: [Co(NH₃)₄Cl₂]Cl, which gives the complex cation and one chloride, i.e. 2 ions (this is the green/violet cis–trans pair).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-24","question":"The total number of lone pairs on the xenon atoms in XeF₂, XeF₄ and XeOF₄ together is:","options":["4","5","6","7"],"answer":2,"explanation":"XeF₂: 2 bond pairs + 3 lone pairs (linear). XeF₄: 4 bond pairs + 2 lone pairs (square planar). XeOF₄: 5 bond pairs (Xe=O counts as one) + 1 lone pair (square pyramidal). Total = 3 + 2 + 1 = 6.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-25","question":"Which statement about group 15 elements is INCORRECT?","options":["NH₃ has a higher boiling point than PH₃","The H–E–H bond angle decreases from NH₃ to AsH₃","Nitrogen forms pπ–pπ multiple bonds, whereas phosphorus does not do so readily","The reducing character of the hydrides decreases from NH₃ to BiH₃"],"answer":3,"explanation":"The E–H bond becomes longer and weaker down the group, so the hydrides release hydrogen more easily: reducing character increases from NH₃ to BiH₃. The other statements are correct (hydrogen bonding in NH₃; decreasing bond angle as the lone pair becomes more s-like).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-26","question":"The number of P–O–P linkages in a molecule of P₄O₁₀ is:","options":["4","6","10","12"],"answer":1,"explanation":"P₄O₁₀ keeps the P₄ tetrahedron: each of the six edges carries a bridging oxygen (6 P–O–P bonds), and each phosphorus has one terminal P=O (4 oxygens), giving 6 + 4 = 10 oxygens. P₄O₆ has the same six bridges but no terminal oxygens.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-27","question":"The equivalent mass of KMnO₄ (molar mass 158 g mol⁻¹) when it acts as an oxidant in neutral or faintly alkaline medium is:","options":["31.6 g","52.7 g","79.0 g","158 g"],"answer":1,"explanation":"In neutral/faintly alkaline medium MnO₄⁻ + 2H₂O + 3e⁻ → MnO₂ + 4OH⁻ (Mn goes from +7 to +4, 3 electrons), so equivalent mass = 158/3 = 52.7 g. In acidic medium it is 158/5 = 31.6 g and in strongly alkaline medium 158/1 = 158 g.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-28","question":"Which of the following complexes is optically active?","options":["trans-[Co(en)₂Cl₂]⁺","cis-[Co(en)₂Cl₂]⁺","cis-[Pt(NH₃)₂Cl₂]","[Ni(NH₃)₆]²⁺"],"answer":1,"explanation":"cis-[Co(en)₂Cl₂]⁺ has no plane or centre of symmetry and exists as non-superimposable mirror images. The trans isomer has a symmetry plane, square-planar cis-[Pt(NH₃)₂Cl₂] is planar (achiral), and [Ni(NH₃)₆]²⁺ with identical ligands is achiral.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-29","question":"How many of the following statements are correct? (i) Partial hydrolysis of XeF₆ gives XeOF₄. (ii) The electron gain enthalpy of fluorine is less negative than that of chlorine. (iii) HF is a stronger acid than HCl in water. (iv) Helium is mixed with oxygen for deep-sea diving because of its very low solubility in blood.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct: XeF₆ + H₂O → XeOF₄ + 2HF; fluorine's small, crowded 2p shell makes its electron gain enthalpy less negative than chlorine's. (iii) is wrong: the very strong H–F bond and H-bonding make HF the weakest hydrohalic acid (HI > HBr > HCl > HF).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-30","question":"How many of the following ions are colourless in aqueous solution: Sc³⁺, Zn²⁺, Ti⁴⁺, Cu²⁺?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Colour in transition-metal ions arises from d–d transitions, which need a partly filled d subshell. Sc³⁺ (d⁰), Ti⁴⁺ (d⁰) and Zn²⁺ (d¹⁰) are colourless; Cu²⁺ (d⁹) is blue. So three are colourless.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-31","question":"The coordination number of cobalt in [Co(en)₃]³⁺ is:","options":["3","6","4","9"],"answer":1,"explanation":"Ethane-1,2-diamine is bidentate; three en ligands give 3 × 2 = 6 donor atoms.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-32","question":"The oxidation state of nickel in [Ni(CO)₄] is:","options":["0","+2","+4","−2"],"answer":0,"explanation":"CO is a neutral ligand and the complex is neutral, so Ni is in the zero oxidation state.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-33","question":"Which oxide of nitrogen is a brown gas?","options":["N₂O","N₂O₅","NO₂","NO"],"answer":2,"explanation":"NO₂ is a brown, paramagnetic gas that dimerises to colourless N₂O₄. N₂O and NO are colourless gases; N₂O₅ is a colourless solid.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-p-block-coordination-34","question":"When an alkali is added to an orange solution of potassium dichromate, the colour changes to:","options":["Green, because Cr³⁺ is formed","Purple, because MnO₄⁻ is formed","Yellow, because Cr₂O₇²⁻ changes into CrO₄²⁻","Colourless, because chromium is reduced"],"answer":2,"explanation":"Cr₂O₇²⁻ + 2OH⁻ ⇌ 2CrO₄²⁻ + H₂O. Chromium stays +6; only the dichromate–chromate equilibrium shifts with pH.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-35","question":"On heating, phosphorous acid (H₃PO₃) disproportionates to give:","options":["H₃PO₂ and H₃PO₄","P₄O₁₀ and H₂O","H₃PO₄ and PH₃","PH₃ and H₃PO₂"],"answer":2,"explanation":"4H₃PO₃ → 3H₃PO₄ + PH₃: P(+3) goes to +5 and −3. This, along with its P–H bond, makes H₃PO₃ a reducing agent.","difficulty":"hard","source":"NEET"},
  {"id":"chem-p-block-coordination-36","question":"The effective atomic number (EAN) of iron in K₄[Fe(CN)₆] is:","options":["26","38","36","24"],"answer":2,"explanation":"Fe²⁺ has 26 − 2 = 24 electrons; six CN⁻ ligands donate 12 more: EAN = 36, the electron count of krypton.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-37","question":"[Co(NH₃)₅Br]SO₄ and [Co(NH₃)₅(SO₄)]Br are examples of:","options":["Linkage isomerism","Coordination isomerism","Ionisation isomerism","Hydrate isomerism"],"answer":2,"explanation":"The two compounds exchange an ion between the coordination sphere and the counter-ion position, so they give different ions in solution (the first gives a BaSO₄ precipitate, the second gives AgBr).","difficulty":"hard","source":"NEET"},
  {"id":"chem-p-block-coordination-38","question":"The spin-only magnetic moment of [CoF₆]³⁻ is about:","options":["5.92 BM","2.83 BM","4.90 BM","0 BM"],"answer":2,"explanation":"Co³⁺ is d⁶; F⁻ is a weak-field ligand, so the complex is high-spin (t₂g⁴e_g²) with 4 unpaired electrons: μ = √(4 × 6) = 4.90 BM.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-39","question":"How many of the following statements are correct? (A) HF has the highest boiling point among the hydrogen halides. (B) The bond dissociation enthalpy order is Cl₂ > Br₂ > F₂ > I₂. (C) Fluorine shows only the −1 oxidation state in its compounds. (D) HClO₄ is a stronger acid than HClO.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. A: hydrogen bonding in HF; B: F₂ is anomalously weak because of lone-pair repulsion in the small molecule; C: F is the most electronegative element; D: more oxygen atoms stabilise the conjugate base.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-40","question":"The crystal field stabilisation energy of the high-spin complex [Fe(H₂O)₆]²⁺ (ignoring pairing energy) is:","options":["−0.6 Δ₀","0","−2.4 Δ₀","−0.4 Δ₀"],"answer":3,"explanation":"Fe²⁺ is d⁶; with weak-field H₂O the configuration is t₂g⁴e_g². CFSE = 4(−0.4) + 2(+0.6) = −0.4 Δ₀. −2.4 Δ₀ is the low-spin value.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-41","question":"The number of geometrical isomers of the square planar complex [Pt(NH₃)(Br)(Cl)(py)] is:","options":["4","3","6","2"],"answer":1,"explanation":"For square planar [Mabcd], fixing a and placing each of b, c or d trans to it gives three distinct isomers. Tetrahedral Mabcd would show no geometrical isomerism.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-42","question":"The number of moles of KMnO₄ needed to oxidise one mole of ferrous oxalate (FeC₂O₄) completely in acidic medium is:","options":["1.0","0.2","0.4","0.6"],"answer":3,"explanation":"Fe²⁺ → Fe³⁺ gives 1 e⁻ and C₂O₄²⁻ → 2CO₂ gives 2 e⁻: 3 e⁻ per FeC₂O₄. MnO₄⁻ → Mn²⁺ takes 5 e⁻, so 3/5 = 0.6 mol. 0.4 mol counts only the oxalate.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-p-block-coordination-43","question":"Assertion (A): Zn, Cd and Hg are not regarded as transition elements. Reason (R): They have completely filled d orbitals both in the ground state and in their common oxidation states.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true and R explains A: a transition element must have an incompletely filled d subshell in the atom or in a common ion; Zn²⁺, Cd²⁺ and Hg²⁺ are all d¹⁰.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-p-block-coordination-44","question":"Match the oxoacid (Column I) with its structural feature (Column II). (a) H₃PO₂, (b) H₃PO₃, (c) H₄P₂O₇, (d) H₂S₂O₈. (1) Contains a P–O–P linkage; (2) Contains two P–H bonds; (3) Contains one P–H bond; (4) Contains an O–O (peroxide) linkage.","options":["a-2, b-3, c-1, d-4","a-1, b-3, c-2, d-4","a-2, b-3, c-4, d-1","a-3, b-2, c-1, d-4"],"answer":0,"explanation":"Hypophosphorous acid has two P–H (monobasic), phosphorous acid one P–H (dibasic), pyrophosphoric acid a P–O–P bridge, and peroxodisulphuric acid an –O–O– bridge.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-p-block-coordination-45","question":"Which of the following complexes is diamagnetic?","options":["[CoF₆]³⁻","[Ni(NH₃)₆]²⁺","[Co(NH₃)₆]³⁺","[Fe(CN)₆]³⁻"],"answer":2,"explanation":"Co³⁺ (d⁶) with strong-field NH₃ is low-spin t₂g⁶, all paired. [Fe(CN)₆]³⁻ (low-spin d⁵) has 1 unpaired electron, [CoF₆]³⁻ has 4 and [Ni(NH₃)₆]²⁺ (d⁸) has 2.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-p-block-coordination-46", "question": "Which noble gas is mixed with oxygen in the breathing gas of deep-sea divers, because it is much less soluble in blood than nitrogen?", "options": ["Neon", "Argon", "Helium", "Krypton"], "answer": 2, "explanation": "Helium's very low solubility in blood avoids the 'bends' caused by dissolved nitrogen coming out of solution during ascent. It is also used to fill balloons and in cryogenics.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-p-block-coordination-47", "question": "The denticity of the ethylenediaminetetraacetate ion (EDTA⁴⁻) is:", "options": ["4", "6", "2", "8"], "answer": 1, "explanation": "EDTA⁴⁻ binds through two nitrogen atoms and four carboxylate oxygens, i.e. six donor atoms (hexadentate). It is used to estimate Ca²⁺ and Mg²⁺ in hard water.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-p-block-coordination-48", "question": "In Werner's theory of coordination compounds, the primary valency of the metal:", "options": ["Is non-ionisable and equals the coordination number", "Is directional and fixes the geometry", "Is satisfied only by neutral molecules", "Is ionisable and corresponds to the oxidation state"], "answer": 3, "explanation": "Primary valencies are ionisable, satisfied by negative ions, and correspond to the oxidation state. Secondary valencies are non-ionisable, equal the coordination number and are directional, giving the geometry.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-p-block-coordination-49", "question": "Bleaching by moist sulphur dioxide is temporary, unlike bleaching by chlorine, because SO₂ bleaches by:", "options": ["Oxidation", "Reduction", "Hydrolysis", "Dehydration"], "answer": 1, "explanation": "SO₂ + 2H₂O → H₂SO₄ + 2[H]; the nascent hydrogen reduces coloured matter to colourless products, which are slowly re-oxidised by air and regain colour. Chlorine bleaches by oxidation, which is permanent.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-p-block-coordination-50", "question": "Which allotrope of phosphorus is the most reactive?", "options": ["Red phosphorus", "Black phosphorus", "White phosphorus", "All allotropes are equally reactive"], "answer": 2, "explanation": "White phosphorus consists of discrete P₄ tetrahedra with strained 60° bond angles, so it is highly reactive, glows in air and is stored under water. Red (polymeric) and black (layered) phosphorus are far less reactive.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-p-block-coordination-51", "question": "Which hydrogen halide is the strongest acid in aqueous solution?", "options": ["HF", "HCl", "HBr", "HI"], "answer": 3, "explanation": "Acid strength rises from HF to HI because the H–X bond becomes longer and weaker (bond enthalpy falls from about 574 to 299 kJ mol⁻¹). HF is a weak acid despite fluorine's high electronegativity.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-52", "question": "The IUPAC name of [Co(NH₃)₅Cl]Cl₂ is:", "options": ["Chloridopentaamminecobalt(III) chloride", "Pentaamminechloridocobalt(II) chloride", "Pentaamminechloridocobalt(III) chloride", "Pentaamminecobalt(III) chloride chloride"], "answer": 2, "explanation": "Ligands are named in alphabetical order (ammine before chlorido). The complex ion carries a charge of +2 (two Cl⁻ outside), so x + 5(0) + (−1) = +2 and Co is +3.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-53", "question": "The oxidation state of chromium in the blue peroxide CrO₅ (which contains two peroxo groups) is:", "options": ["+10", "+5", "+6", "+8"], "answer": 2, "explanation": "CrO₅ has one Cr=O oxygen (−2) and two O₂²⁻ peroxo groups (−1 per O): x − 2 − 4 = 0, so x = +6. Assuming every oxygen is −2 gives the impossible value +10.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-54", "question": "Which of the following contains a nitrogen–nitrogen bond?", "options": ["N₂O₅", "N₂O₃", "HNO₂", "NO₂"], "answer": 1, "explanation": "N₂O₃ is O=N–NO₂, with a direct N–N bond. In N₂O₅ the two NO₂ groups are bridged through oxygen (O₂N–O–NO₂); HNO₂ and NO₂ contain only one N atom.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-55", "question": "Complete hydrolysis of XeF₆ gives:", "options": ["XeOF₄", "XeO₂F₂", "XeO₄", "XeO₃"], "answer": 3, "explanation": "XeF₆ + 3H₂O → XeO₃ + 6HF. Partial hydrolysis gives XeOF₄ and then XeO₂F₂; xenon stays in the +6 state throughout.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-56", "question": "The spin-only magnetic moment of [Ti(H₂O)₆]³⁺ is about:", "options": ["2.83 BM", "1.73 BM", "0 BM", "3.87 BM"], "answer": 1, "explanation": "Ti³⁺ is 3d¹, with one unpaired electron: μ = √(n(n + 2)) = √3 = 1.73 BM.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-57", "question": "The crystal field stabilisation energy of a tetrahedral d⁷ complex (such as [CoCl₄]²⁻), in terms of the tetrahedral splitting Δt, is:", "options": ["−0.8 Δt", "−0.6 Δt", "−1.2 Δt", "−1.8 Δt"], "answer": 2, "explanation": "In a tetrahedral field the e set lies 0.6Δt below the barycentre and t₂ lies 0.4Δt above. d⁷ is e⁴ t₂³ (pairing is never forced, since Δt is small): CFSE = 4(−0.6) + 3(+0.4) = −2.4 + 1.2 = −1.2 Δt.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-58", "question": "[Co(NH₃)₆][Cr(CN)₆] and [Cr(NH₃)₆][Co(CN)₆] are examples of:", "options": ["Coordination isomerism", "Linkage isomerism", "Ionisation isomerism", "Hydrate isomerism"], "answer": 0, "explanation": "Coordination isomers arise when ligands swap between the cationic and anionic complex entities of a salt. Ionisation isomers exchange a ligand with a counter-ion; linkage isomers differ in the donor atom of an ambidentate ligand.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-59", "question": "The correct order of acid strength of the hypohalous acids is:", "options": ["HOI > HOBr > HOCl", "HOBr > HOCl > HOI", "HOCl > HOI > HOBr", "HOCl > HOBr > HOI"], "answer": 3, "explanation": "In H–O–X the more electronegative halogen pulls electron density from the O–H bond and stabilises the OX⁻ anion; Cl > Br > I in electronegativity, so HOCl is the strongest. The order is opposite to that of the hydrogen halides.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-60", "question": "How many of the following statements are correct? (A) Ozone is diamagnetic. (B) Rhombic sulphur is the stable allotrope at room temperature. (C) H₂O has the highest boiling point among the hydrides of group 16. (D) Thermal stability decreases in the order H₂O > H₂S > H₂Se > H₂Te.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "(A) O₃ has all electrons paired. (B) rhombic (α) sulphur is stable below 369 K. (C) hydrogen bonding gives water by far the highest boiling point. (D) the H–E bond weakens down the group. All four are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-61", "question": "Which of the following is an inner-orbital complex that is also paramagnetic?", "options": ["[Co(NH₃)₆]³⁺", "[CoF₆]³⁻", "[Cr(NH₃)₆]³⁺", "[Fe(H₂O)₆]³⁺"], "answer": 2, "explanation": "Cr³⁺ (3d³) leaves two 3d orbitals empty, so it uses them for d²sp³ (inner-orbital) bonding while its three electrons stay unpaired (3.87 BM). [Co(NH₃)₆]³⁺ is inner-orbital but diamagnetic; [CoF₆]³⁻ and [Fe(H₂O)₆]³⁺ are outer-orbital (sp³d²).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-62", "question": "Match the reaction of concentrated H₂SO₄ (Column I) with the property it shows (Column II). (a) C₁₂H₂₂O₁₁ → 12C + 11H₂O; (b) Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O; (c) NaCl + H₂SO₄ → NaHSO₄ + HCl; (d) 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. (1) Dehydrating agent; (2) Oxidising agent; (3) Low volatility, displacing a more volatile acid; (4) Dibasic acid in neutralisation.", "options": ["a-2, b-1, c-3, d-4", "a-1, b-3, c-2, d-4", "a-1, b-2, c-4, d-3", "a-1, b-2, c-3, d-4"], "answer": 3, "explanation": "Charring sugar removes H and O as water (dehydration); copper is oxidised while S(+6) is reduced to SO₂; non-volatile H₂SO₄ drives out volatile HCl; and it neutralises two NaOH per molecule as a dibasic acid. So a-1, b-2, c-3, d-4.", "difficulty": "very-hard", "source": "NEET"},
  {"id": "chem-p-block-coordination-63", "question": "[Ti(H₂O)₆]³⁺ absorbs light most strongly at 498 nm. The crystal field splitting energy Δo is about (h = 6.626 × 10⁻³⁴ J s, c = 3 × 10⁸ m/s, N_A = 6.022 × 10²³):", "options": ["120 kJ mol⁻¹", "240 kJ mol⁻¹", "2.4 kJ mol⁻¹", "480 kJ mol⁻¹"], "answer": 1, "explanation": "The d¹ electron is promoted t₂g → e_g, so Δo = hcN_A/λ = (6.626 × 10⁻³⁴ × 3 × 10⁸ × 6.022 × 10²³)/(498 × 10⁻⁹) = 0.1197/4.98 × 10⁻⁷ ≈ 2.40 × 10⁵ J mol⁻¹ = 240 kJ mol⁻¹.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-p-block-coordination-64", "question": "Assertion (A): Nitrogen does not form a pentahalide, whereas phosphorus forms PCl₅. Reason (R): Nitrogen has no d orbitals in its valence shell and cannot expand its covalency beyond four.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Nitrogen's valence shell (n = 2) has only s and p orbitals, so its maximum covalency is 4 (as in NH₄⁺). Phosphorus can use 3d orbitals to form five bonds. R correctly explains A.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-65", "question": "Which of the following orders of ligand field strength (spectrochemical series) is correct?", "options": ["I⁻ < Cl⁻ < NH₃ < H₂O < CN⁻", "Cl⁻ < I⁻ < H₂O < CN⁻ < NH₃", "I⁻ < Cl⁻ < H₂O < NH₃ < CN⁻", "CN⁻ < NH₃ < H₂O < Cl⁻ < I⁻"], "answer": 2, "explanation": "Halides are weak-field ligands (I⁻ weakest), water is intermediate, NH₃ is stronger than H₂O, and CN⁻ (a π-acceptor) is among the strongest. The series is experimental and does not follow ligand charge.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-66", "question": "Of [Co(NH₃)₆]³⁺ and [CoF₆]³⁻, which absorbs light of longer wavelength, and why?", "options": ["[CoF₆]³⁻, because F⁻ is a weak-field ligand giving a smaller Δo; the complex is high-spin and paramagnetic", "[Co(NH₃)₆]³⁺, because NH₃ produces a larger Δo", "[CoF₆]³⁻, because F⁻ is a strong-field ligand giving a larger Δo", "Both absorb at the same wavelength, since both contain Co³⁺"], "answer": 0, "explanation": "Absorbed energy = Δo = hc/λ, so a smaller Δo means a longer wavelength. F⁻ is weak-field, so [CoF₆]³⁻ has the smaller Δo and is high-spin (4 unpaired electrons), while [Co(NH₃)₆]³⁺ is low-spin and diamagnetic.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-67", "question": "How many of the following statements are correct? (A) Fluorine shows only the −1 oxidation state in its compounds. (B) Iodine is much more soluble in aqueous KI than in water because I₃⁻ is formed. (C) HF is a stronger acid than HCl in water. (D) The active constituent of bleaching powder is calcium hypochlorite, Ca(OCl)₂.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(A) true: fluorine is the most electronegative element and has no d orbitals. (B) true: I₂ + I⁻ → I₃⁻. (C) false: the strong H–F bond and hydrogen bonding make HF a weak acid. (D) true. Three are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-68", "question": "The total number of P–OH groups in one molecule each of H₄P₂O₇, H₃PO₃ and H₃PO₂ is:", "options": ["9", "7", "8", "6"], "answer": 1, "explanation": "H₄P₂O₇ has 4 ionisable P–OH groups; H₃PO₃ has 2 (one H is bonded directly to P); H₃PO₂ has 1 (two P–H bonds). Total = 4 + 2 + 1 = 7. Counting every hydrogen as P–OH would give 4 + 3 + 3 = 10, which explains why these acids are tetra-, di- and monobasic.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-69", "question": "How many of the following complexes can show geometrical isomerism: [Pt(NH₃)₂Cl₂] (square planar), [Co(NH₃)₄Cl₂]⁺, [Zn(NH₃)₂Cl₂] (tetrahedral), [Co(NH₃)₅Cl]²⁺, [Co(NH₃)₃Cl₃]?", "options": ["2", "3", "4", "5"], "answer": 1, "explanation": "Square planar MA₂B₂ (cis/trans), octahedral MA₄B₂ (cis/trans) and octahedral MA₃B₃ (fac/mer) all show geometrical isomers: 3. Tetrahedral MA₂B₂ has all positions adjacent, and MA₅B has only one arrangement.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-70", "question": "Which statement about metal carbonyls is NOT correct?", "options": ["The C–O bond order increases when CO binds to the metal", "The metal–carbon bond has both σ and π character", "Back donation strengthens the M–C bond and weakens the C–O bond", "[Ni(CO)₄] is tetrahedral and diamagnetic"], "answer": 0, "explanation": "CO donates its lone pair to the metal (σ) and the metal donates d electrons back into the empty π* orbital of CO (π back bonding). Filling π* lowers the C–O bond order, lengthening the bond, so the first statement is the wrong one. Ni(0) in [Ni(CO)₄] is sp³, with all electrons paired.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-p-block-coordination-71", "question": "The IUPAC name of the neutral complex [Pt(NH₃)₂Cl(NO₂)] (nitrite bound through N) is:", "options": ["Diamminechloridonitrito-N-platinum(II)", "Diamminechloridonitrito-N-platinate(II)", "Chloridodiamminenitrito-N-platinum(II)", "Diamminechloridonitrito-O-platinum(II)"], "answer": 0, "explanation": "Ligands are listed alphabetically ignoring the 'di' prefix (ammine, chlorido, nitrito), and N-bonded nitrite is nitrito-N. The complex is neutral, so the metal keeps its ordinary name; the '-ate' ending is used only for anionic complexes.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-72", "question": "Boric acid, H₃BO₃, is a weak monobasic acid in water because it:", "options": ["Loses one of its three O–H protons, the other two being too weakly acidic", "Accepts an OH⁻ from water (Lewis acid), forming [B(OH)₄]⁻ and releasing H⁺", "Is a protonic acid that ionises completely", "Forms H₂BO₃⁻ by losing an H atom bonded directly to boron"], "answer": 1, "explanation": "B(OH)₃ + 2H₂O ⇌ [B(OH)₄]⁻ + H₃O⁺: the electron-deficient boron accepts a hydroxide from water, so one H⁺ is set free per molecule. It does not donate its own O–H protons like a Brønsted acid, which is why adding a cis-diol (glycerol, mannitol) strengthens it enough to be titrated.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-73", "question": "In the brown complex formed in the brown ring test, [Fe(H₂O)₅(NO)]²⁺, the oxidation state of iron is:", "options": ["+2", "+3", "+1", "0"], "answer": 2, "explanation": "NO binds as NO⁺ (nitrosonium) in this complex and water is neutral, so Fe + (+1) = +2 gives Fe = +1. Its magnetic moment (≈ 3.9 BM, three unpaired electrons) fits high-spin Fe⁺ (3d⁷); assuming neutral NO gives the tempting +2.", "difficulty": "moderate", "source": "JEE Main"},
  {"id":"chem-p-block-coordination-74","question":"The number of geometrical isomers of [Co(NH₃)₃Cl₃], and the number that are optically active, are:","options":["4 geometrical isomers; two optically active","3 geometrical isomers; one optically active","2 geometrical isomers; both optically active","2 geometrical isomers (fac and mer); none optically active"],"answer":3,"explanation":"An octahedral MA₃B₃ complex exists only as fac (three like ligands on one face) and mer (three in a plane through the metal). Both have mirror planes, so neither is chiral.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-p-block-coordination-75","question":"In a silicate anion each SiO₄ tetrahedron shares exactly two of its oxygen atoms with neighbouring tetrahedra. The empirical formula of the anion is:","options":["(SiO₃)ₙ²ⁿ⁻","(Si₂O₅)ₙ²ⁿ⁻","SiO₄⁴⁻","Si₂O₇⁶⁻"],"answer":0,"explanation":"Each shared O counts ½ to a given Si: 2 unshared + 2 × ½ = 3 O per Si, giving SiO₃ with charge 4 − 2 = 2−, as in cyclic silicates and single-chain pyroxenes. Sharing one O gives Si₂O₇⁶⁻ (pyrosilicate), sharing three gives sheet Si₂O₅²⁻.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-p-block-coordination-76","question":"Ozone is passed through a neutral (borate-buffered) KI solution. Which statement is correct?","options":["O₃ is reduced to water and no gas is evolved","I₂ is liberated and O₂ is released: O₃ + 2I⁻ + H₂O → I₂ + O₂ + 2OH⁻, so titrating the I₂ estimates the ozone","KI reduces O₃ to O²⁻, which stays as K₂O","O₃ oxidises I⁻ to IO₃⁻ only, with no free iodine"],"answer":1,"explanation":"Only one oxygen atom of O₃ does the oxidising; the other two leave as O₂. The I₂ produced is titrated with thiosulphate, which is the standard way of estimating ozone. The borate buffer keeps the solution from becoming strongly alkaline, where I₂ would disproportionate.","difficulty":"hard","source":"JEE Main"},
  {"id": "chem-p-block-coordination-78", "question": "XeF₂ reacts with PF₅. The product is best formulated as:", "options": ["XeF₄ + PF₃", "[PF₄]⁺[XeF₃]⁻", "[XeF]⁺[PF₆]⁻", "Xe + PF₇"], "answer": 2, "explanation": "XeF₂ acts as a fluoride-ion donor towards the strong fluoride acceptor PF₅: XeF₂ + PF₅ → [XeF]⁺[PF₆]⁻. Phosphorus cannot exceed six-coordination in PF₆⁻, and there is no change of oxidation state, so redox products like XeF₄ + PF₃ are wrong.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-79", "question": "NF₃ has a much smaller dipole moment (≈ 0.2 D) than NH₃ (≈ 1.5 D) and has practically no basic character. The reason is:", "options": ["NF₃ is planar, while NH₃ is pyramidal", "N in NF₃ has no lone pair", "N–F bonds are non-polar", "In NF₃ the N–F bond moments point away from N, opposing the lone-pair moment, and the electronegative F atoms pull electron density from the lone pair"], "answer": 3, "explanation": "Both molecules are pyramidal with a lone pair on N. In NH₃ the N–H bond moments point towards N and add to the lone-pair moment; in NF₃ they point towards F and largely cancel it. The −I effect of three fluorines also makes the lone pair far less available, so NF₃ is not a useful base.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-80", "question": "Iodine monochloride, ICl, is hydrolysed by water. The products are:", "options": ["HCl and HOI", "HI and HOCl", "HCl, HI and O₂", "I₂ and Cl₂"], "answer": 0, "explanation": "In I–Cl, chlorine is more electronegative, so iodine is the positive end and combines with OH⁻ (giving HOI) while chloride takes H⁺ (giving HCl). Writing HI + HOCl puts the hydroxyl on the more electronegative halogen, which is the trap.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-81", "question": "The total number of stereoisomers (geometrical and optical) of an octahedral complex [Ma₂b₂c₂], where a, b and c are different monodentate ligands, is:", "options": ["5", "6", "4", "8"], "answer": 1, "explanation": "Geometrical isomers: all three pairs trans (1); one pair trans and two pairs cis (3, choosing which pair is trans); all three pairs cis (1) — total 5. The all-cis isomer has no mirror plane and exists as a pair of enantiomers, so the total is 5 + 1 = 6.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id":"chem-p-block-coordination-82","question":"Match the species (Column I) with its shape (Column II). (a) I₃⁻, (b) ICl₄⁻, (c) BrF₅, (d) XeO₃. (1) Square pyramidal, (2) Linear, (3) Trigonal pyramidal, (4) Square planar.","options":["a-3, b-4, c-1, d-2","a-2, b-1, c-4, d-3","a-2, b-4, c-1, d-3","a-2, b-4, c-3, d-1"],"answer":2,"explanation":"I₃⁻: 2 bond pairs + 3 lone pairs on the central I, linear. ICl₄⁻: 4 bp + 2 lp, square planar. BrF₅: 5 bp + 1 lp, square pyramidal. XeO₃: 3 σ bond pairs + 1 lp (π bonds do not count), trigonal pyramidal.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-p-block-coordination-83", "question": "How many of the following statements are correct? (A) In aqueous solution Tl⁺ is more stable than Tl³⁺. (B) PbO₂ oxidises concentrated HCl to Cl₂. (C) SnCl₂ acts as an oxidising agent, being reduced to tin metal. (D) The stability of the +2 oxidation state decreases down group 14 from Ge to Pb.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and B are correct consequences of the inert pair effect: the lower state becomes more stable down the group, so Tl³⁺ and Pb(IV) are oxidising. C is wrong: SnCl₂ is a well-known reducing agent (Sn²⁺ → Sn⁴⁺). D is wrong: +2 becomes more stable from Ge to Pb, not less.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-84", "question": "How many of the following statements about diborane, B₂H₆, are correct? (A) It has four terminal B–H bonds and two bridging B–H–B three-centre two-electron bonds. (B) All six hydrogen atoms lie in one plane. (C) Each boron atom is roughly sp³ hybridised. (D) The bridging B–H bonds are longer than the terminal B–H bonds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct. B is wrong: the two borons and four terminal H atoms lie in one plane, while the two bridging H atoms lie above and below that plane. The bridging bonds are 'banana' 3c–2e bonds, longer (≈ 133 pm) than the terminal 2c–2e bonds (≈ 119 pm).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-p-block-coordination-85","question":"Match the ammonium salt heated (Column I) with the main products (Column II). (a) NH₄NO₂, (b) NH₄NO₃, (c) (NH₄)₂Cr₂O₇, (d) NH₄Cl. (1) N₂O and H₂O, (2) N₂, Cr₂O₃ and H₂O, (3) NH₃ and HCl (recombining on cooling), (4) N₂ and H₂O only.","options":["a-1, b-4, c-2, d-3","a-4, b-2, c-1, d-3","a-3, b-1, c-2, d-4","a-4, b-1, c-2, d-3"],"answer":3,"explanation":"Salts with an oxidising anion undergo internal redox: NH₄NO₂ → N₂ + 2H₂O; NH₄NO₃ → N₂O + 2H₂O (dangerously above ~500 K); (NH₄)₂Cr₂O₇ → N₂ + Cr₂O₃ + 4H₂O (the 'volcano'). NH₄Cl, with a non-oxidising anion, simply dissociates into NH₃ and HCl, which recombine in the cooler part of the tube.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-p-block-coordination-86","question":"The total number of unpaired electrons in one ion each of [Fe(CN)₆]⁴⁻, [Fe(H₂O)₆]²⁺, [Mn(CN)₆]³⁻ and [Cr(H₂O)₆]³⁺ is:","options":["9","13","11","7"],"answer":0,"explanation":"[Fe(CN)₆]⁴⁻: Fe²⁺ d⁶, strong field, t₂g⁶: 0. [Fe(H₂O)₆]²⁺: d⁶, weak field, t₂g⁴e_g²: 4. [Mn(CN)₆]³⁻: Mn³⁺ d⁴, strong field, t₂g⁴: 2. [Cr(H₂O)₆]³⁺: d³: 3. Total 0 + 4 + 2 + 3 = 9; treating the Mn complex as high spin gives 11.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-p-block-coordination-87","question":"Which of the following mononuclear metal carbonyls is paramagnetic?","options":["[Cr(CO)₆]","[V(CO)₆]","[Ni(CO)₄]","[Fe(CO)₅]"],"answer":1,"explanation":"V (5 valence electrons) + 6 CO (12 electrons) = 17 electrons, one short of 18, so [V(CO)₆] has one unpaired electron (it is readily reduced to the 18-electron [V(CO)₆]⁻). Cr(CO)₆, Fe(CO)₅ and Ni(CO)₄ each have 18 valence electrons and are diamagnetic.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-p-block-coordination-88","question":"For the isoelectronic series [V(CO)₆]⁻, [Cr(CO)₆] and [Mn(CO)₆]⁺, the correct order of C–O bond strength (C–O stretching frequency) is:","options":["[Cr(CO)₆] > [Mn(CO)₆]⁺ > [V(CO)₆]⁻","[V(CO)₆]⁻ > [Cr(CO)₆] > [Mn(CO)₆]⁺","[Mn(CO)₆]⁺ > [Cr(CO)₆] > [V(CO)₆]⁻","All are equal, since the species are isoelectronic"],"answer":2,"explanation":"The more electron-rich the metal, the more it back-donates into the π* orbitals of CO, which weakens the C–O bond. The anion back-donates most (ν(CO) ≈ 1860 cm⁻¹) and the cation least (≈ 2090 cm⁻¹), so the cation has the strongest C–O bond. Being isoelectronic does not make the back-bonding equal, because the nuclear charges differ.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-p-block-coordination-89","question":"The total number of stereoisomers of [Co(en)(NH₃)₂Cl₂]⁺ is:","options":["3","2","6","4"],"answer":3,"explanation":"Geometrical isomers: NH₃ groups trans (Cl's cis), Cl's trans (NH₃ cis), and both pairs cis — 3. The first two have a mirror plane; the isomer with both NH₃ cis and both Cl cis has none and exists as two enantiomers. Total 3 + 1 = 4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-p-block-coordination-90","question":"Solid KMnO₄ is heated strongly (about 513 K). The oxidation states of manganese in the solid manganese-containing products, and the moles of O₂ released per mole of KMnO₄, are:","options":["+6 and +4; 0.5 mol","+6 and +2; 1 mol","+4 only; 0.75 mol","+7 and +4; 0.25 mol"],"answer":0,"explanation":"2KMnO₄ → K₂MnO₄ + MnO₂ + O₂: half the Mn goes to manganate (+6) and half to MnO₂ (+4). Mn(+7 → +6) gains 1 e⁻ and Mn(+7 → +4) gains 3 e⁻, i.e. 4 e⁻ per 2 KMnO₄, exactly the 4 e⁻ lost when two O²⁻ become one O₂; so 1 mol O₂ per 2 mol KMnO₄= 0.5 mol.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-p-block-coordination-91", "question": "How many of the following oxoacids contain an S–S bond: H₂S₂O₃, H₂S₂O₄, H₂S₂O₅, H₂S₂O₆, H₂S₂O₇, H₂S₂O₈?", "options": ["3", "4", "2", "5"], "answer": 1, "explanation": "Thiosulphuric (S–S, one S replaces an O of sulphuric acid), dithionous (HO₂S–SO₂H), disulphurous/pyrosulphurous (HO–S(O)–S(O)₂–OH) and dithionic (HO₃S–SO₃H) acids have S–S bonds: 4. Pyrosulphuric acid has an S–O–S bridge and peroxodisulphuric acid an S–O–O–S bridge, so both lack an S–S bond.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-p-block-coordination-92", "question": "How many of the following species are paramagnetic: NO, NO₂, N₂O₄, N₂O₃, ClO₂, O₃, O₂⁻ (in KO₂)?", "options": ["3", "5", "4", "2"], "answer": 2, "explanation": "NO (11 valence electrons), NO₂ (17) and ClO₂ (19) are odd-electron molecules, and O₂⁻ has one unpaired electron in a π* orbital: 4. N₂O₄ and N₂O₃ (dimer and NO–NO₂ adduct) have all electrons paired, and O₃ is diamagnetic.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-p-block-coordination-93", "question": "Which statement about the structures of solid PCl₅ and solid PBr₅ is correct?", "options": ["Both exist as trigonal bipyramidal PX₅ molecules", "Solid PCl₅ is [PCl₄]⁺[PCl₆]⁻, whereas solid PBr₅ is [PBr₄]⁺Br⁻", "Solid PCl₅ is [PCl₄]⁺Cl⁻ and solid PBr₅ is [PBr₄]⁺[PBr₆]⁻", "Both are [PX₄]⁺[PX₆]⁻"], "answer": 1, "explanation": "In the solid, PCl₅ ionises to tetrahedral [PCl₄]⁺ and octahedral [PCl₆]⁻. Six large bromine atoms cannot fit round one phosphorus, so [PBr₆]⁻ is not formed and solid PBr₅ is [PBr₄]⁺Br⁻. Only in the vapour (and non-polar solvents) is PCl₅ a trigonal bipyramidal molecule.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-p-block-coordination-94", "question": "Assertion (A): SiCl₄ is rapidly hydrolysed by water, whereas CCl₄ is not hydrolysed at all under ordinary conditions. Reason (R): Silicon can accept a lone pair from water into its vacant 3d orbitals (and is large enough to be attacked), while carbon has no d orbitals in its valence shell and is shielded by four Cl atoms.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "SiCl₄ + 4H₂O → Si(OH)₄ + 4HCl proceeds by water attacking Si to form a five-coordinate intermediate, which carbon (no low-lying d orbitals, small and crowded) cannot form. CCl₄ is thermodynamically unstable to hydrolysis but kinetically inert, which is exactly what R explains.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-p-block-coordination-95","question":"The volume of 0.1 M KMnO₄ needed to oxidise 50 mL of 0.1 M KI in neutral (faintly alkaline) solution is:","options":["10 mL","200 mL","50 mL","100 mL"],"answer":3,"explanation":"In neutral medium MnO₄⁻ gains 3e⁻ (→ MnO₂) and I⁻ is oxidised to IO₃⁻ (6e⁻): 2MnO₄⁻ + I⁻ + H₂O → 2MnO₂ + IO₃⁻ + 2OH⁻. KI = 5 mmol needs 10 mmol KMnO₄ = 100 mL. Assuming the acidic reaction (I⁻ → I₂, MnO₄⁻ → Mn²⁺) gives 1 mmol = 10 mL.","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
